import{Ft as e,St as t,bt as n,ht as r,qt as i,t as a,vt as o,xt as s,zt as c}from"./chunks/framework.B0CLzZNn.js";var l=JSON.parse(`{"title":"会话系统","description":"","frontmatter":{},"headers":[],"relativePath":"guide/session-related/conversation.md","filePath":"v1/guide/session-related/conversation.md","lastUpdated":1793342047000}`),u={name:`guide/session-related/conversation.md`};function d(a,l,u,d,f,p){let m=c(`NolebasePageProperties`),h=c(`VPNolebaseInlineLinkPreview`),g=c(`NolebaseGitChangelog`);return e(),o(`div`,null,[l[6]||=r(`h1`,{id:`会话系统`,tabindex:`-1`},[s(`会话系统 `),r(`a`,{class:`header-anchor`,href:`#会话系统`,"aria-label":`Permalink to “会话系统”`},`​`)],-1),t(m),l[7]||=n(`<p>ChatLuna 的核心概念是「会话」，不再是之前旧版本中的「房间」。</p><p>一条消息进入 ChatLuna 后，会依次经过三个层级：路由、预设通道、会话。</p><p>路由决定当前消息的触发者，应该使用哪一个会话，是否需要共享。</p><p>预设通道会将同一路由拆分为多条并行的会话，在同一个路由内可以分开多条预设。</p><p>会话则是实际承载上下文的单元。</p><p>如果目标位置上还没有活跃会话，ChatLuna 会在首次使用时自动创建。</p><h2 id="会话" tabindex="-1">会话 <a class="header-anchor" href="#会话" aria-label="Permalink to “会话”">​</a></h2><p>会话是一段完整的上下文，包含聊天历史、当前模型、当前预设、当前聊天模式和当前状态（如活跃、已归档）。</p><p>使用 <code>chatluna.new</code> 可以创建一段新的上下文。</p><div class="tip custom-block"><p class="custom-block-title">提示</p><p><code>chatluna.clear</code> 目前是 <code>chatluna.new</code> 的别名，目前是新建一条会话再切换过去的。</p></div><h2 id="路由" tabindex="-1">路由 <a class="header-anchor" href="#路由" aria-label="Permalink to “路由”">​</a></h2><p>路由决定了谁共享同一组会话。</p><p>共享路由下，同一个群的成员共用同一组会话，适用于公共助手、项目群协作，以及需要多人接续上一轮上下文的场景。</p><p>个人路由下，同一个群的每个成员各自拥有独立的会话，适用于群内同时运行多个独立任务，或用户希望保持互不干扰的上下文。</p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>私聊始终使用个人路由。<code>defaultGroupRouteMode</code> 只影响群聊，可选值为 <code>shared</code> 和 <code>personal</code>。</p></div><h2 id="预设通道" tabindex="-1">预设通道 <a class="header-anchor" href="#预设通道" aria-label="Permalink to “预设通道”">​</a></h2><p>预设通道可以将同一路由拆分为多条并行工作线。例如一个群中可以同时存在默认通道（用于普通聊天）、<code>translator</code> 通道（用于翻译）和 <code>reviewer</code> 通道（用于润色）。每条通道独立维护自己的当前会话。</p><p>选择通道有两种方式。一是通过命令的 <code>-p &lt;preset&gt;</code> 参数显式指定：</p><div class="language-powershell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">chatluna.current </span><span style="--shiki-light:#c62739;--shiki-dark:#56B6C2;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">p translator</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">chatluna.use.mode plugin </span><span style="--shiki-light:#c62739;--shiki-dark:#56B6C2;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">p reviewer</span></span></code></pre></div><p>二是发送一条以预设别名开头的普通消息，ChatLuna 会将其路由到对应通道。</p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>如果整条消息只有别名本身，且消息为纯文本，ChatLuna 通常会展示该通道当前的会话信息，而非发起新一轮聊天。</p></div><h2 id="自动创建会话" tabindex="-1">自动创建会话 <a class="header-anchor" href="#自动创建会话" aria-label="Permalink to “自动创建会话”">​</a></h2><p>首次在某条路由上聊天，或首次向某条预设通道发送消息时，ChatLuna 会自动创建会话。自动创建时使用的默认值来自 <code>defaultModel</code>、<code>defaultPreset</code>、<code>defaultChatMode</code> 以及当前作用域上的路由规则。</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>这些默认值只影响后续新建的会话，不会覆盖已有会话。</p></div><h2 id="当前会话设置与路由规则" tabindex="-1">当前会话设置与路由规则 <a class="header-anchor" href="#当前会话设置与路由规则" aria-label="Permalink to “当前会话设置与路由规则”">​</a></h2><p><code>chatluna.use.*</code> 系列命令修改的是当前会话正在使用的配置。</p><p>包括 <code>chatluna.use.model</code>（切换模型）、<code>chatluna.use.preset</code>（切换预设）和 <code>chatluna.use.mode</code>（切换聊天模式）。</p><p><code>chatluna.rule.*</code> 系列命令修改的是当前作用域（群聊或私聊）后续创建会话时的默认行为，包括：</p><ul><li><code>chatluna.rule.model</code>：设置新会话默认模型，或固定模型</li><li><code>chatluna.rule.preset</code>：切换活跃预设通道，或设置新会话默认预设</li><li><code>chatluna.rule.mode</code>：设置新会话默认聊天模式，或固定模式</li><li><code>chatluna.rule.share</code>：查看或切换共享路由 / 个人路由</li><li><code>chatluna.rule.lock</code>：锁定当前作用域上的会话管理操作</li></ul><h2 id="聊天模式的修改方式" tabindex="-1">聊天模式的修改方式 <a class="header-anchor" href="#聊天模式的修改方式" aria-label="Permalink to “聊天模式的修改方式”">​</a></h2>`,30),r(`p`,null,[l[1]||=s(`聊天模式的修改涉及多个层级，详见 `,-1),t(h,{href:`./../chat-chain/chat-mode.html`},{default:i(()=>[...l[0]||=[s(`聊天模式`,-1)]]),_:1}),l[2]||=s(`。`,-1)]),l[8]||=n(`<p><code>chatluna.use.mode</code> 用于修改当前会话，<code>chatluna.new -c</code> 可以在在新建会话时指定，<code>chatluna.rule.mode</code> 修改当前作用域后续新会话的默认模式，<code>defaultChatMode</code> 则是全局默认值。</p><h2 id="会话生命周期" tabindex="-1">会话生命周期 <a class="header-anchor" href="#会话生命周期" aria-label="Permalink to “会话生命周期”">​</a></h2><p>ChatLuna 提供了一组会话管理命令：<code>chatluna.new</code>（创建）、<code>chatluna.switch</code>（切换）、<code>chatluna.rename</code>（重命名）、<code>chatluna.archive</code>（归档）、<code>chatluna.restore</code>（恢复）、<code>chatluna.export</code>（导出）、<code>chatluna.compress</code>（压缩会话历史）和 <code>chatluna.delete</code>（删除）。</p>`,3),r(`p`,null,[l[4]||=s(`详细用法参见 `,-1),t(h,{href:`./../useful-commands/conversation.html`},{default:i(()=>[...l[3]||=[s(`会话指令`,-1)]]),_:1}),l[5]||=s(`。`,-1)]),l[9]||=n(`<h2 id="指定目标会话" tabindex="-1">指定目标会话 <a class="header-anchor" href="#指定目标会话" aria-label="Permalink to “指定目标会话”">​</a></h2><p>许多命令支持手动指定目标会话。目前接受列表序号、会话 ID 或会话标题三种写法。你可以先执行 <code>chatluna.list</code> 来获取完整的会话列表，日常使用列表序号，需要精确定位时使用会话 ID。</p><h2 id="常见使用场景" tabindex="-1">常见使用场景 <a class="header-anchor" href="#常见使用场景" aria-label="Permalink to “常见使用场景”">​</a></h2><p>将 <code>defaultGroupRouteMode</code> 设为 <code>shared</code>，同一群的成员将默认共用同一路由；设为 <code>personal</code>，每个成员拥有独立的路由和会话集合。</p><p>如需多条工作线并行，为预设配置清晰的别名，将不同任务分配到不同通道即可。也可以发送以预设别名开头的普通消息，将内容路由到对应通道。</p><p>如需统一某个群后续新会话的默认聊天模式，使用 <code>chatluna.rule.mode browsing</code>。如需锁定防止修改，追加 <code>-f</code> 参数。</p><h2 id="迁移说明" tabindex="-1">迁移说明 <a class="header-anchor" href="#迁移说明" aria-label="Permalink to “迁移说明”">​</a></h2><p>新版本启动时，旧的 <code>room</code> 数据会自动迁移到会话系统。</p><p>如果迁移失败，则只能清空所有旧数据。</p>`,9),t(g)])}var f=a(u,[[`render`,d]]);export{l as __pageData,f as default};